def review_gap(state: dict, root: Path, cwd: Path, cycle: int) -> str | None:
    from cli import gate

    cycles = state.get("review_cycles") or []
    if not cycles or not isinstance(cycles[-1], dict):
        return "review has no recorded cycle artifact"
    if cycles[-1].get("cycle") != cycle:
        return "review artifact belongs to another cycle"
    path = cwd / cycles[-1].get("review_file", "")
    try:
        text = path.read_text()
    except OSError as error:
        return f"review artifact unreadable: {error}"
    gap = gate.check(text, ["alice", "blake", "bob"], require_codex_guard=False)
    if gap:
        return gap
    for persona, rubric in (
        ("Alice", root.parent / "review-work-completion/references/rubric.md"),
        ("Blake", root.parent / "review-blindly/references/rubric.md"),
    ):
        rules = re.findall(r"^([RB]\d+):", rubric.read_text(), re.MULTILINE)
        section = re.search(
            rf"^## {persona}\b[^\n]*\n(.*?)(?=^## |\Z)", text, re.MULTILINE | re.DOTALL
        )
        if not section or any(
            not re.search(rf"^{rule}: (?:pass|fail)\b", section[1], re.MULTILINE) for rule in rules
        ):
            return f"{persona} lacks the complete source rubric"
    try:
        audit_path = (
            cwd
            / "docs/dev/project-management/autopilot/reports"
            / f"{Path(state['prd']).stem}-implementation-models.json"
        )
        snapshot = json.loads(audit_path.read_text())["snapshot"]
        if (
            snapshot.get("cycle") != cycle
            or snapshot.get("prd") != state.get("prd")
            or snapshot.get("work_start_sha") != state.get("work_start_sha")
        ):
            return "review audit belongs to another PRD, cycle or work range"
        providers = driver.audited_review_providers(snapshot, cwd)
        if state.get("phase") == "done" and driver.implementation_fingerprint(
            state
        ) != driver.implementation_fingerprint(snapshot):
            return "implementation changed since the converged review"
    except (ValueError, OSError, KeyError, IndexError, TypeError) as error:
        return f"review provider routing: {error}"
    if not re.search(r"^provider_review_guard: satisfied$", text, re.MULTILINE):
        return "missing model-provider review guard"
    for provider in providers:
        for lens in ("alice", "blake", "bob"):
            gap = bob_gap(
                text,
                cwd,
                cycle,
                state.get("prd", ""),
                lens,
                provider,
                driver.implementation_fingerprint(snapshot),
            )
            if gap:
                return gap
    verdicts = state.get("doubts_rubric_verdicts") or []
    ids = {item.get("rule_id") for item in verdicts if isinstance(item, dict)}
    if not {f"D{n}" for n in range(1, 6)}.issubset(ids):
        return "state lacks the complete Bob doubt rubric"
    return None


def bob_gap(
    text: str,
    cwd: Path,
    cycle: int,
    prd: str,
    lens: str = "bob",
    provider: str | None = None,
    fingerprint: str | None = None,
) -> str | None:
    key = f"autocodex_{lens}_{provider}_receipt" if provider else "autocodex_bob_receipt"
    match = re.search(rf"^{key}: (.+)$", text, re.MULTILINE)
    if not match:
        return f"missing {key}"
    try:
        receipt = json.loads((cwd / match[1].strip()).read_text())
        raw = Path(receipt["output"]).read_bytes()
        if fingerprint is not None and receipt.get("implementation_fingerprint") != fingerprint:
            return "review receipt belongs to a different implementation snapshot"
        if (
            receipt["provider"] != ("codex" if provider == "openai" else "claude")
            or (
                provider is not None
                and (
                    receipt.get("lens") != lens
                    or driver.model_provider_for_review(receipt["model"]) != provider
                )
            )
            or receipt["cycle"] != cycle
            or receipt["prd"] != prd
            or receipt["root"] != str(cwd.resolve())
        ):
            return "Bob receipt is stale or names the wrong provider"
        if hashlib.sha256(raw).hexdigest() != receipt["sha256"]:
            return "Bob output changed after dispatch"
        captured = Path(receipt["raw"]).read_bytes()
        if hashlib.sha256(captured).hexdigest() != receipt["raw_sha256"]:
            return "Bob raw evidence changed after dispatch"
        events = driver.Events(receipt["provider"])
        for line in captured.splitlines():
            events.accept(line)
        if not events.success or events.text.encode() != raw:
            return "review output does not match a successful provider result"
        for rule in driver.review_rules(lens):
            if not re.search(rf"^{rule}: (?:pass|fail)\b", raw.decode(), re.MULTILINE):
                return f"{lens} missing {rule}"
    except (OSError, ValueError, KeyError, TypeError) as error:
        return f"invalid Bob receipt: {error}"
    return None


class CodexLoop(loop.Loop):
    def __init__(

### Outcomes:

The first three rows describe a cycle that did NOT converge — the Cap check above already routed a converged cycle to the last row. A cycle whose only survivors are Medium/Low has converged; it does not "proceed to Phase 6" for another cycle.

- **All auto-fixable, no deferrals, no blockers** → proceed to Phase 6
- **Has deferrals but no blockers** → run `autopilot defer --prd <filename> --batch <batch_id> --json '<record>'` for each deferred item, proceed to Phase 6 with auto-fixable items only
- **Has blocking escalation** →
  - **Interactive:** PAUSE. Present only the blocking issue(s) to user via `AskUserQuestion`. Wait for decision. After user responds, proceed to Phase 6.
  - **Loop mode (`$_AUTOPILOT_LOOP` set):** there is no human to answer — do NOT pause the batch. Follow the **Loop-mode stall procedure** (`references/recovery.md`) with `site: "blocking_escalation"`, recording the blocking issue(s) in the deferred JSON `detail`, and continue the batch. The parked PRD, on un-park, re-enters the build gate and the decision resurfaces interactively.
- **Converged (no unresolved CRITICAL/HIGH)** → before treating the cycle as converged, run `autopilot gate --review-file <this cycle's review file> --require-codex-guard --assert-constraint-met` (flag semantics: `cli/gate.py` module docstring; PRD 00107 absorbed the old `check_review_file.py` path, which survives as a shim). It checks the constraint line only, so a converging cycle may legitimately carry `Verdict: N findings`. Exit 0 → the doubt-roster constraint certified; the review-rework loop has converged (all lenses, including blind and doubt, passed this cycle). On this path the wrapper records the convergence row at review-phase exit; write nothing (see **Convergence metric** below). Run the **Tail sweep** below, then hand off to the finalize session (see below). Exit 2 → the constraint did NOT hold; do NOT converge this cycle. Do NOT re-run the Cap check above — its own convergence test already needs this same gate (see "Cap check" above), so re-entering it only recreates this same bullet. Instead, classify the unmet constraint as one unresolved CRITICAL finding and route forward directly on `state.cycle` vs `state.rework_cap`: below cap → continue to Phase 6 for another review cycle; at cap → the existing cap-out machinery applies with no new mechanism — **loop mode**: the "Any unresolved CRITICAL finding" branch above (stall via `references/recovery.md` → Loop-mode stall procedure, `site: "cap_critical"`; the batch continues); **interactive**: the Cap-pause behavior above (include the constraint among the collected `unresolved_findings`). The batch keeps draining either way; this does not create a new batch-halt class.

### Convergence metric

`cli/loop.py` (`Loop._append_metrics`) appends the `review_converged` row to `docs/dev/project-management/autopilot/loop-metrics.jsonl` and its `ledger/` mirror when a session launched as `review` exits with `next_phase: "done"` - one row per PRD, written after that session's own row, never from skill prose. Both paths above (converged, and the loop-mode cap-out) exit that way, so neither writes anything. Its shape:

```json
{"event":"review_converged","prd","batch","cycles_to_converge":<state.cycle>,"outcome":"converged"|"cap_deferred","ts":<epoch>,"rework_cap":<state.rework_cap|null>,"build_models":[...],"attempt_tiers":[...],"tasks_planned":<int|null>,"tasks_completed":<int|null>,"tasks_in_prd":<int|null>,"cycles":[{"cycle":1,"reviewers":[...]|null,"verdict":"converged"|<int>|null,"findings":{"critical","high","medium","low"}|null}, ...]}
```

Where each field comes from:

- `outcome`: `cap_deferred` when `deferred_decisions` holds a cap-overflow record, else `converged`.
- `cycles[]`: one entry per cycle, read from `docs/dev/project-management/reviews/<prd stem>-review-<n>.md` or `-review-<nn>.md`; null when the file is missing.
- `build_models`: this PRD's build session rows.
- `attempt_tiers`: `tasks[].attempts[].model`.
- `tasks_planned` / `tasks_completed`: `tasks_total` / `tasks_completed`, with the `state.tasks` fallback.
- `tasks_in_prd`: the wip PRD's checkbox lines.

`cli/render_metrics.load_rows` still drops event rows while `load_event_rows` reads them, and `autopilot render report` prints them as `- Run conditions:`.

### Tail sweep

Runs once, on the converged outcome above, after the review file is saved and before the finalize hand-off. The Medium/Low tail is **swept, not dropped**: normal `/autopilot:work` tasks fix it, then the PRD finalizes. No new verification machinery.

**1. Select.** Take the converging cycle's actionable Medium/Low findings. Exclude settled deferrals, findings this gate discarded, findings routed to verification (their check runs in step 7; sweeping them would rebuild the task this routing exists to remove), and anything already in `deferred_decisions` — a decision already taken is not swept again. **Zero actionable Medium/Low → skip the sweep entirely** and go straight to the finalize hand-off (today's clean path, unchanged).

**2. Create.** Build `chosen_findings` from step 1's selection exactly as Phase 6's "Dispatch rework" source 2 does: one entry per swept finding, each `"classification": "fix"`, with `severity`, `file`, `issue` and `found_by` copied verbatim from its `## Consolidated Findings` row. Write it with the Write tool to `docs/dev/tmp/<prd-stem>-tail-sweep-<cycle>-findings.json`, then run ONE `autopilot review-close --review-file <this cycle's review file> --state <state.json> --batch-id tail-sweep --findings docs/dev/tmp/<prd-stem>-tail-sweep-<cycle>-findings.json --default-tier <tier>` call (tier: the `/autopilot:plan-tasks` classifier output when its inputs are available, otherwise `sonnet`; no 🔴 reaches the sweep, so no `default_model` floor applies). It groups the swept findings into one task per group (at most 4, never zero), gives each the same `### Findings (verbatim)` block Phase 6 D-tasks carry (PRD 00095), and appends each id to `state.rework_task_ids`, in one transaction. `--batch-id tail-sweep` is what names each task `[D{cycle}] Tail sweep: <theme>`, the group's `name_hint` supplying `<theme>`; the literal `Tail sweep` prefix is what Phase 4's rotation-resume rule reads (PRD 00196, pinned at `skills/run-autopilot/scripts/test_review_resume_prose.py:55`). The existing max-2-parallel rework rule applies unchanged. Exit codes are read as in Phase 6's "Dispatch rework": 0 applied, `already applied` continue, any other refusal a sub-skill failure.

`doubts_rubric_verdicts` and `review_lenses` close-out are already recorded by the decision-gate call earlier in the cycle. `review-close` re-derives both from the same review file, so this call's write to those fields is a no-op by design, not a bug and not a second roster close-out.

**3. Dispatch.** Invoke `/autopilot:work` in rework mode exactly as Phase 6 does. The mandatory one-verification-pass constraint is satisfied by `/autopilot:work`'s own pipeline — tests-first 2.7 for behavioral fixes, the 5.5 gate, 5.6 self-deslop, 5.7 per-task review. Nothing extra runs here.

**4. Finalize.** When `/autopilot:work` returns, go to the finalize hand-off below. **Do NOT increment `state.cycle`, do NOT hand off review → review, and do NOT run another review cycle.** Phase 5 never reopens after convergence — reopening rebuilds the polish loop this gate exists to remove. Print, before the hand-off banner:

```
── converged (cycle {n}): {k} medium/low findings swept ────────────
```

